import{_ as i,o as t,c as s,ae as n}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"Lifecycle Event Emission, Persistence, and Integration Tests","description":"","frontmatter":{"work_package_id":"WP02","title":"Lifecycle Event Emission, Persistence, and Integration Tests","lane":"done","dependencies":["WP01"],"base_branch":"014-terminal-to-lane-session-binding-WP01","base_commit":"f4f8a3b249b6f995e509dcfa42f4bb9a1d64811f","created_at":"2026-03-01T13:31:56.932100+00:00","subtasks":["T005","T006","T007","T008"],"phase":"Phase 2 - Durability and Integration","assignee":"","agent":"claude-haiku","shell_pid":"64856","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/014-terminal-to-lane-session-binding/tasks/WP02-lifecycle-events-persistence-and-tests.md","filePath":"specs/014-terminal-to-lane-session-binding/tasks/WP02-lifecycle-events-persistence-and-tests.md"}'),a={name:"specs/014-terminal-to-lane-session-binding/tasks/WP02-lifecycle-events-persistence-and-tests.md"};function r(o,e,l,c,d,p){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="work-package-prompt-wp02-lifecycle-event-emission-persistence-and-integration-tests" tabindex="-1">Work Package Prompt: WP02 - Lifecycle Event Emission, Persistence, and Integration Tests <a class="header-anchor" href="#work-package-prompt-wp02-lifecycle-event-emission-persistence-and-integration-tests" aria-label="Permalink to &quot;Work Package Prompt: WP02 - Lifecycle Event Emission, Persistence, and Integration Tests&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Emit binding lifecycle events (bound, rebound, unbound, validation-failed) on the internal bus for downstream consumers.</li><li>Implement durable persistence so bindings survive runtime restarts.</li><li>Subscribe to lane/session lifecycle events for automatic binding invalidation.</li><li>Deliver integration tests covering persistence, recovery, lifecycle propagation, and latency benchmarks.</li></ul><p>Success criteria:</p><ul><li>All binding state changes emit corresponding events on the bus.</li><li>After runtime restart, bindings are restored from durable storage with &gt;=98% accuracy.</li><li>Lane detach/cleanup events automatically invalidate or close affected terminal bindings.</li><li>Latency benchmarks pass: &lt;5ms validation, &lt;2ms lookup at p95 with 500+ bindings.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/014-terminal-to-lane-session-binding/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/014-terminal-to-lane-session-binding/spec.md</code></li><li>Terminal registry: <code>apps/runtime/src/registry/terminal_registry.ts</code> (WP01)</li><li>Binding middleware: <code>apps/runtime/src/registry/binding_middleware.ts</code> (WP01)</li><li>Internal event bus: <code>apps/runtime/src/protocol/bus.ts</code> (spec 001)</li><li>Lane lifecycle: spec 008</li><li>Session lifecycle: spec 009</li></ul><p>Constraints:</p><ul><li>Persistence must not block the hot path; async writes with in-memory primary.</li><li>Keep files under 500 lines.</li><li>TypeScript + Bun runtime.</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP02</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t005-implement-binding-lifecycle-event-emission" tabindex="-1">Subtask T005 - Implement binding lifecycle event emission <a class="header-anchor" href="#subtask-t005-implement-binding-lifecycle-event-emission" aria-label="Permalink to &quot;Subtask T005 - Implement binding lifecycle event emission&quot;">​</a></h3><ul><li>Purpose: notify downstream consumers (UI, audit, orphan detection) of all binding state changes.</li><li>Steps: <ol><li>Implement <code>BindingEventEmitter</code> in <code>apps/runtime/src/registry/binding_events.ts</code>: a. Define event topic constants: <code>terminal.binding.bound</code>, <code>terminal.binding.rebound</code>, <code>terminal.binding.unbound</code>, <code>terminal.binding.validation_failed</code>. b. Define event payload schema: <code>terminalId</code>, <code>binding</code> (the triple), <code>previousBinding</code> (if rebound), <code>state</code>, <code>timestamp</code>, <code>correlationId</code>.</li><li>Wire the event emitter into <code>TerminalRegistry</code> CRUD operations: a. <code>register()</code> -&gt; emit <code>bound</code>. b. <code>rebind()</code> -&gt; emit <code>rebound</code> with previous and new binding. c. <code>unregister()</code> -&gt; emit <code>unbound</code>. d. Middleware <code>validation_failed</code> state transition -&gt; emit <code>validation_failed</code>.</li><li>Publish events via the internal bus (<code>apps/runtime/src/protocol/bus.ts</code>).</li><li>Include correlation ID from the originating operation (terminal creation, lane switch, etc.).</li><li>Register event topics in protocol topic registry if applicable.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/registry/binding_events.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/registry/terminal_registry.ts</code> (wire events)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/registry/binding_middleware.ts</code> (wire validation_failed event)</li></ul></li><li>Validation: <ul><li>Unit test: register terminal, assert <code>bound</code> event emitted with correct payload.</li><li>Unit test: rebind terminal, assert <code>rebound</code> event includes previous and new binding.</li><li>Unit test: unregister terminal, assert <code>unbound</code> event emitted.</li><li>Unit test: trigger validation failure, assert <code>validation_failed</code> event.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t006-implement-durable-persistence-adapter" tabindex="-1">Subtask T006 - Implement durable persistence adapter <a class="header-anchor" href="#subtask-t006-implement-durable-persistence-adapter" aria-label="Permalink to &quot;Subtask T006 - Implement durable persistence adapter&quot;">​</a></h3><ul><li>Purpose: ensure binding state survives runtime restarts for recovery.</li><li>Steps: <ol><li>Implement <code>BindingPersistence</code> in <code>apps/runtime/src/registry/persistence.ts</code>: a. Interface: <code>save(bindings: TerminalBinding[]): Promise&lt;void&gt;</code>, <code>load(): Promise&lt;TerminalBinding[]&gt;</code>, <code>clear(): Promise&lt;void&gt;</code>. b. Implementation: file-backed JSON store or embedded SQLite (prefer simplicity; file-backed JSON for slice-1).</li><li>Implement async write strategy: a. On binding change, schedule a debounced write (e.g., 500ms) to avoid write storms. b. On explicit flush (e.g., before graceful shutdown), write immediately. c. Keep in-memory registry as the primary source of truth; persistence is for recovery only.</li><li>Implement load-on-startup: a. On runtime startup, load persisted bindings into the registry. b. Re-validate each loaded binding against current lane/session state. c. Discard bindings whose lanes or sessions no longer exist (emit <code>unbound</code> events).</li><li>Implement integrity checks: a. Write a checksum with the persisted data. b. On load, verify checksum; if corrupt, discard and start fresh with warning.</li><li>File location: use the app&#39;s data directory (e.g., <code>~/.helios/data/binding_registry.json</code>).</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/registry/persistence.ts</code></li></ul></li><li>Validation: <ul><li>Integration test: register 10 bindings, flush, reload, assert all 10 restored.</li><li>Integration test: corrupt the persistence file, reload, assert graceful recovery with warning.</li><li>Integration test: register bindings, kill lane, reload, assert stale bindings discarded.</li><li>Benchmark: write 500 bindings, assert flush completes in &lt;100ms.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t007-implement-lane-session-lifecycle-subscription-for-automatic-invalidation" tabindex="-1">Subtask T007 - Implement lane/session lifecycle subscription for automatic invalidation <a class="header-anchor" href="#subtask-t007-implement-lane-session-lifecycle-subscription-for-automatic-invalidation" aria-label="Permalink to &quot;Subtask T007 - Implement lane/session lifecycle subscription for automatic invalidation&quot;">​</a></h3><ul><li>Purpose: automatically invalidate terminal bindings when their lane or session is detached, cleaned up, or terminated.</li><li>Steps: <ol><li>Subscribe to lane lifecycle events from spec 008: a. On <code>lane.detached</code> or <code>lane.cleaned_up</code>: look up all terminals bound to that lane via <code>getByLane(laneId)</code>. b. For each affected terminal: either unregister (close terminal) or transition to <code>unbound</code> state depending on the event type. c. Emit corresponding <code>unbound</code> events for each affected terminal.</li><li>Subscribe to session lifecycle events from spec 009: a. On <code>session.terminated</code> or <code>session.expired</code>: look up all terminals bound to that session via <code>getBySession(sessionId)</code>. b. Unregister affected terminals and emit <code>unbound</code> events.</li><li>Implement recovery-aware suppression: a. If a lane or session is in <code>recovering</code> state, do not invalidate its bindings. b. Cross-reference active recovery operations before invalidating.</li><li>Wire subscriptions in the registry initialization path.</li><li>Log invalidation actions for debugging.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/registry/terminal_registry.ts</code> (lifecycle subscriptions)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/registry/binding_events.ts</code> (event emission)</li></ul></li><li>Validation: <ul><li>Integration test: emit lane.cleaned_up event, verify all terminals for that lane are unregistered.</li><li>Integration test: emit session.terminated event, verify affected terminals unregistered.</li><li>Integration test: emit lane.detached while lane is recovering, verify bindings are NOT invalidated.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t008-add-integration-tests-and-latency-benchmarks" tabindex="-1">Subtask T008 - Add integration tests and latency benchmarks <a class="header-anchor" href="#subtask-t008-add-integration-tests-and-latency-benchmarks" aria-label="Permalink to &quot;Subtask T008 - Add integration tests and latency benchmarks&quot;">​</a></h3><ul><li>Purpose: validate the complete binding lifecycle including persistence, restart recovery, and performance SLOs.</li><li>Steps: <ol><li>Create <code>apps/runtime/tests/integration/registry/binding_lifecycle.test.ts</code>: a. Test full lifecycle: register -&gt; rebind -&gt; unregister with event verification at each step. b. Test concurrent binding changes across multiple terminals. c. Test binding consistency after rapid lane switches.</li><li>Create <code>apps/runtime/tests/integration/registry/persistence.test.ts</code>: a. Test save and reload cycle with 100 bindings. b. Test restart recovery: register bindings, simulate restart, verify restoration. c. Test corrupt file recovery. d. Test stale binding pruning on reload.</li><li>Create <code>apps/runtime/tests/integration/registry/lane_session_integration.test.ts</code>: a. Test lane cleanup triggers binding invalidation. b. Test session termination triggers binding invalidation. c. Test recovery suppression (no invalidation during active recovery).</li><li>Create <code>apps/runtime/tests/integration/registry/latency_benchmarks.test.ts</code>: a. Register 500+ bindings. b. Benchmark lookup by terminal_id: assert p95 &lt; 2ms. c. Benchmark lookup by lane_id: assert p95 &lt; 2ms. d. Benchmark validation middleware: assert p95 &lt; 5ms.</li><li>Aim for &gt;=85% line coverage across all registry modules.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/registry/binding_lifecycle.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/registry/persistence.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/registry/lane_session_integration.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/registry/latency_benchmarks.test.ts</code></li></ul></li><li>Parallel: Yes (after T005/T006/T007 are implemented).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Integration tests with real file-backed persistence.</li><li>Lifecycle event verification using bus event capture.</li><li>Latency benchmarks with 500+ bindings for SLO validation.</li><li>Aim for &gt;=85% line coverage.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: persistence write storms during rapid binding changes.</li><li>Mitigation: debounced writes with immediate flush on shutdown.</li><li>Risk: lifecycle event subscription misses events during startup race.</li><li>Mitigation: subscribe before loading persisted bindings; re-validate after load.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm events are emitted for every binding state change path.</li><li>Confirm persistence uses async writes with immediate flush on shutdown.</li><li>Confirm lane/session lifecycle subscriptions correctly invalidate affected bindings.</li><li>Confirm recovery-aware suppression prevents false invalidation.</li><li>Confirm latency benchmarks use sufficient binding counts.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z -- system -- lane=planned -- Prompt created.</li><li>2026-03-01T13:31:57Z – claude-haiku – shell_pid=64856 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:34:18Z – claude-haiku – shell_pid=64856 – lane=done – Implemented: Event emission, persistence adapter, lifecycle subscriptions, and comprehensive integration tests</li></ul>',28)])])}const g=i(a,[["render",r]]);export{m as __pageData,g as default};
